/// 操作日志表\nmodel OperationLog {\n  /// 主键\n  id           BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 操作人 id\n  userId       BigInt?  @map(\"user_id\") @db.BigInt\n  /// 操作人账号\n  username     String?  @db.VarChar(50)\n  /// 模块\n  module       String   @db.VarChar(50)\n  /// 动作\n  action       String   @db.VarChar(50)\n  /// HTTP 方法\n  method       String   @db.VarChar(10)\n  /// 请求 URL\n  url          String   @db.VarChar(255)\n  /// 请求参数（密码脱敏）\n  params       String?  @db.Text\n  /// 变更前数据（JSON 文本；敏感字段已脱敏、超长已截断，仅支持的写操作会写）\n  beforeData   String?  @map(\"before_data\") @db.VarChar(2000)\n  /// 变更后数据（JSON 文本；口径同 before_data）\n  afterData    String?  @map(\"after_data\") @db.VarChar(2000)\n  /// 耗时 ms\n  duration     Int      @default(0)\n  /// 1 成功 / 0 失败\n  result       Int      @db.TinyInt\n  /// 失败信息\n  errorMessage String?  @map(\"error_message\") @db.VarChar(500)\n  /// 客户端 IP\n  ip           String?  @db.VarChar(50)\n  /// IP 归属地（ip2region 离线解析：国家 省份 城市 运营商）\n  location     String?  @db.VarChar(100)\n  /// 创建时间\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  @@index([createdAt])\n  @@map(\"sys_operation_log\")\n}\n\n/// HTTP 访问日志表（页面查询用；操作者为写入时快照，不与 sys_user 建外键）\nmodel HttpLog {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 请求完成时间（本地时区 +08:00）\n  time       DateTime @db.DateTime(3)\n  /// HTTP 方法\n  method     String   @db.VarChar(10)\n  /// 请求 URL（含 query）\n  url        String   @db.VarChar(1024)\n  /// HTTP 状态码\n  statusCode Int      @map(\"status_code\") @db.SmallInt\n  /// 耗时 ms\n  duration   Int      @default(0) @db.Int\n  /// 客户端 IP\n  ip         String?  @db.VarChar(64)\n  /// IP 归属地（ip2region 离线解析：国家 省份 城市 运营商）\n  location   String?  @db.VarChar(100)\n  /// User-Agent（用户代理）\n  userAgent  String?  @map(\"user_agent\") @db.VarChar(500)\n  /// 操作用户 id（0 为匿名/未登录）\n  userId     BigInt   @default(0) @map(\"user_id\") @db.BigInt\n  /// 操作账号（快照）\n  username   String?  @db.VarChar(50)\n  /// 所属部门 id 快照（0 为无）\n  deptId     BigInt   @default(0) @map(\"dept_id\") @db.BigInt\n  /// 所属部门名称（快照）\n  deptName   String?  @map(\"dept_name\") @db.VarChar(50)\n  /// 查询参数（已脱敏）\n  query      Json?\n  /// 请求体（已脱敏、截断 2KB）\n  reqBody    String?  @map(\"req_body\") @db.Text\n  /// 响应内容（截断 2KB；二进制为占位）\n  resBody    String?  @map(\"res_body\") @db.Text\n\n  @@index([time])\n  @@index([method])\n  @@index([statusCode])\n  @@index([method, time])\n  // 操作者筛选索引：显式声明，保证每一次全新部署都带 idx_user_id / idx_dept_id\n  @@index([userId])\n  @@index([deptId])\n  // 操作者前缀检索索引（列表按 username startsWith 过滤）\n  @@index([username])\n  @@map(\"sys_http_log\")\n}\n\n/**\n * 站内通知（每个接收人一条记录）。\n * 刻意用「每人一条」而不是「公告一条 + 已读关联表」：\n * 收件人规模可控（后台用户），而按人存能直接支持未读数、逐条已读与个人通知（强制下线、改密提醒），\n * 不需要额外的已读关联表与联表查询。\n */\nmodel Notice {\n  /// 主键\n  id         BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 接收人 id\n  userId     BigInt    @map(\"user_id\") @db.BigInt\n  /// 标题\n  title      String    @db.VarChar(200)\n  /// 正文（纯文本，渲染时按纯文本处理，不接受 HTML）\n  content    String    @db.Text\n  /// 类型：1 系统通知 / 2 公告 / 3 安全提醒\n  noticeType Int       @default(1) @map(\"notice_type\") @db.TinyInt\n  /// 点击跳转的前端路由（空 = 不跳转）\n  link       String?   @db.VarChar(255)\n  /// 0 未读 / 1 已读\n  isRead     Int       @default(0) @map(\"is_read\") @db.TinyInt\n  /// 阅读时间\n  readAt     DateTime? @map(\"read_at\")\n  /// 创建人 id（系统自动通知可为空）\n  createdBy  BigInt?   @map(\"created_by\") @db.BigInt\n  /// 创建时间\n  createdAt  DateTime  @default(now()) @map(\"created_at\")\n\n  /// 个人收件箱列表：按人 + 未读优先 + 时间倒序\n  @@index([userId, isRead, createdAt])\n  @@map(\"sys_notice\")\n}\n\n// use prisma-next\n// ↑ 首行不可删：VS Code 的 Prisma 扩展**按文件**判定是否启用 Prisma 7 语言服务，\n//   缺失会回落到 v6 语义并误报 `Argument \"url\" is missing in data source block \"db\"`。\n//\n// 系统与权限：用户 / 角色 / 菜单 / 部门，以及三张关联表\n// 公共约定（snake_case 映射 / 哨兵值 / 注释落库）见 base.prisma。\n/// 用户表\nmodel User {\n  /// 主键\n  id                BigInt    @id @default(autoincrement()) @db.BigInt\n  /// 登录账号\n  username          String    @unique @db.VarChar(50)\n  /// bcrypt 哈希\n  password          String    @db.VarChar(100)\n  /// 昵称\n  nickname          String    @default(\"\") @db.VarChar(50)\n  /// 头像 URL\n  avatar            String?   @db.VarChar(255)\n  /// 邮箱\n  email             String?   @db.VarChar(100)\n  /// 手机号\n  phone             String?   @db.VarChar(20)\n  /// 性别（字典 sys_user_sex），字符串存储以便字典值扩展\n  gender            String?   @db.VarChar(20)\n  /// 1 启用 / 0 禁用\n  status            Int       @default(1) @db.TinyInt\n  /// 最后登录时间\n  lastLoginAt       DateTime? @map(\"last_login_at\")\n  /// 密码最后修改时间\n  passwordChangedAt DateTime? @map(\"password_changed_at\")\n  /// 备注\n  remark            String?   @db.VarChar(255)\n  /// 部门 id（0 表示未分配，故不建外键、也不声明 Prisma 关系）\n  deptId            BigInt    @default(0) @map(\"dept_id\") @db.BigInt\n  /// 创建时间\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n\n  /// 经中间表 UserRole 的直接角色关联。\n  /// ⚠️ 必须走显式中间表 `sys_user_role`（`userRoles.role`），**不要**改回隐式多对多：\n  ///    隐式 `Role[]` 关系会让 Prisma 另建一张 `_userroles` 表，与业务读写的 `sys_user_role`\n  ///    不互通——表现为角色恒为空、权限码为空、所有带权限码的接口 403、前端菜单树为空。\n  userRoles UserRole[]\n\n  @@index([deptId])\n  @@map(\"sys_user\")\n}\n\n/// 角色表\nmodel Role {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 角色名称\n  roleName  String   @map(\"role_name\") @db.VarChar(50)\n  /// 角色编码\n  roleCode  String   @unique @map(\"role_code\") @db.VarChar(50)\n  /// 排序\n  sort      Int      @default(0)\n  /// 1 启用 / 0 禁用\n  status    Int      @default(1) @db.TinyInt\n  /// 数据权限范围：1 全部 / 2 自定义部门 / 3 本部门及以下 / 4 仅本人\n  dataScope Int      @default(1) @map(\"data_scope\") @db.TinyInt\n  /// 备注\n  remark    String?  @db.VarChar(255)\n  /// 创建时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  /// 同样只走显式中间表（见 User 模型上的说明，勿改回隐式多对多）\n  userRoles UserRole[]\n  roleMenus RoleMenu[]\n  roleDepts RoleDept[]\n\n  @@map(\"sys_role\")\n}\n\n/// 菜单权限表\nmodel Menu {\n  /// 主键\n  id         BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 父级 id（0 表示根节点，故不建外键、也不声明 Prisma 自关联）\n  parentId   BigInt   @default(0) @map(\"parent_id\") @db.BigInt\n  /// 菜单名称\n  menuName   String   @map(\"menu_name\") @db.VarChar(50)\n  /// M 目录 / C 菜单 / F 按钮\n  menuType   String   @map(\"menu_type\") @db.Char(1)\n  /// 路由路径\n  path       String?  @db.VarChar(200)\n  /// 组件路径\n  component  String?  @db.VarChar(255)\n  /// 图标\n  icon       String?  @db.VarChar(100)\n  /// 权限标识\n  permission String?  @db.VarChar(100)\n  /// 排序\n  sort       Int      @default(0)\n  /// 1 显示 / 0 隐藏\n  visible    Int      @default(1) @db.TinyInt\n  /// 1 启用 / 0 禁用\n  status     Int      @default(1) @db.TinyInt\n  /// 重定向\n  redirect   String?  @db.VarChar(255)\n  /// 1 缓存 / 0 不缓存\n  keepAlive  Int      @default(0) @map(\"keep_alive\") @db.TinyInt\n  /// 创建时间\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  roleMenus RoleMenu[]\n\n  @@index([parentId])\n  @@map(\"sys_menu\")\n}\n\n/// 部门表\nmodel Dept {\n  /// 主键\n  id        BigInt   @id @default(autoincrement()) @db.BigInt\n  /// 父级 id（0 表示顶级，故不建外键、也不声明 Prisma 自关联）\n  parentId  BigInt   @default(0) @map(\"parent_id\") @db.BigInt\n  /// 类型：1 部门 / 2 岗位（岗位为叶子节点，不能再挂下级）\n  deptType  Int      @default(1) @map(\"dept_type\") @db.TinyInt\n  /// 部门名称\n  deptName  String   @map(\"dept_name\") @db.VarChar(50)\n  /// 排序\n  sort      Int      @default(0)\n  /// 1 启用 / 0 禁用\n  status    Int      @default(1) @db.TinyInt\n  /// 部门负责人\n  leader    String?  @db.VarChar(20)\n  /// 联系电话\n  phone     String?  @db.VarChar(20)\n  /// 邮箱\n  email     String?  @db.VarChar(100)\n  /// 创建时间\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  /// 更新时间\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  roleDepts RoleDept[]\n\n  @@index([parentId])\n  @@map(\"sys_dept\")\n}\n\n/// 用户角色关联表\nmodel UserRole {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 用户 id\n  userId BigInt @map(\"user_id\") @db.BigInt\n  /// 角色 id\n  roleId BigInt @map(\"role_id\") @db.BigInt\n\n  user User @relation(fields: [userId], references: [id])\n  role Role @relation(fields: [roleId], references: [id])\n\n  @@unique([userId, roleId])\n  @@index([roleId])\n  @@map(\"sys_user_role\")\n}\n\n/// 角色菜单关联表\nmodel RoleMenu {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 角色 id\n  roleId BigInt @map(\"role_id\") @db.BigInt\n  /// 菜单 id\n  menuId BigInt @map(\"menu_id\") @db.BigInt\n\n  role Role @relation(fields: [roleId], references: [id])\n  menu Menu @relation(fields: [menuId], references: [id])\n\n  @@unique([roleId, menuId])\n  @@index([menuId])\n  @@map(\"sys_role_menu\")\n}\n\n/// 角色数据权限部门关联表（承载 data_scope=2 的自定义部门集合）\nmodel RoleDept {\n  /// 主键\n  id     BigInt @id @default(autoincrement()) @db.BigInt\n  /// 角色 id\n  roleId BigInt @map(\"role_id\") @db.BigInt\n  /// 部门 id\n  deptId BigInt @map(\"dept_id\") @db.BigInt\n\n  role Role @relation(fields: [roleId], references: [id])\n  dept Dept @relation(fields: [deptId], references: [id])\n\n  @@unique([roleId, deptId])\n  @@index([deptId])\n  @@map(\"sys_role_dept\")\n}\n",
